package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import android.view.inspector.WindowInspector;
import android.graphics.Rect;
import android.widget.TextView;
import java.io.PrintWriter;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.uiautomator.*;
import java.io.File;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;

/** Fake microphone lifecycle only. All scheduler calls are injected; no alarm runtime may open. */
public class SpeakCaptureFlowTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);private SpeakChallengeActivity activity;
    private String step="fixture admission";
    private void await(java.util.function.BooleanSupplier ready){assertTrue(step,device.wait(new Condition<UiDevice,Boolean>(){public Boolean apply(UiDevice ignored){return ready.getAsBoolean();}},5000));}
    private View find(View root,String value,boolean description){if(description?value.contentEquals(root.getContentDescription()==null?"":root.getContentDescription()):root instanceof TextView&&value.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View view=find(group.getChildAt(n),value,description);if(view!=null)return view;}return null;}
    private View focusedWindow(){View found=null;for(View root:WindowInspector.getGlobalWindowViews())if(root.getContext().getPackageName().equals(c.getPackageName())&&root.hasWindowFocus()&&root.isAttachedToWindow()&&root.isLaidOut()&&root.getWidth()>0&&root.getHeight()>0){assertNull("One focused application window",found);found=root;}return found;}
    private void ready(){await(()->{boolean[] yes={false};i.runOnMainSync(()->yes[0]=activity!=null&&!activity.isDestroyed()&&activity.hasWindowFocus()&&focusedWindow()==activity.getWindow().getDecorView());return yes[0];});}
    private void frame(View owner)throws Exception{CountDownLatch drawn=new CountDownLatch(1);i.runOnMainSync(()->{assertSame("Exact focused window before frame",owner,focusedWindow());owner.getViewTreeObserver().registerFrameCommitCallback(drawn::countDown);owner.invalidate();});assertTrue(step+": rendered owned frame",drawn.await(5,TimeUnit.SECONDS));i.runOnMainSync(()->assertSame("Frame retains its exact focused window",owner,focusedWindow()));}
    private void require(String value,boolean description){step="require page "+value;ready();await(()->{boolean[] yes={false};i.runOnMainSync(()->{View target=find(activity.getWindow().getDecorView(),value,description);if(target==null)return;target.requestRectangleOnScreen(new Rect(0,0,target.getWidth(),target.getHeight()),true);Rect visible=new Rect();yes[0]=target.isShown()&&target.getGlobalVisibleRect(visible)&&visible.height()==target.getHeight()&&visible.width()==target.getWidth();});return yes[0];});}
    private boolean hasText(String text){boolean[] found={false};i.runOnMainSync(()->found[0]=find(activity.getWindow().getDecorView(),text,false)!=null);return found[0];}
    private void input(View owner,String value,boolean description)throws Exception{
        step="single owned input "+value;
        await(()->{boolean[] ready={false};i.runOnMainSync(()->{if(focusedWindow()!=owner)return;View target=find(owner,value,description);if(target==null)return;while(!target.isClickable()&&target.getParent() instanceof View)target=(View)target.getParent();if(!target.isClickable()||!target.isEnabled())return;target.requestRectangleOnScreen(new Rect(0,0,target.getWidth(),target.getHeight()),true);Rect visible=new Rect();ready[0]=target.getGlobalVisibleRect(visible)&&visible.height()==target.getHeight()&&visible.width()==target.getWidth();});return ready[0];});
        frame(owner);Rect screen=new Rect();i.runOnMainSync(()->{assertSame(owner,focusedWindow());View target=find(owner,value,description);assertNotNull(step,target);while(!target.isClickable()&&target.getParent() instanceof View)target=(View)target.getParent();assertSame("Control belongs to exact decor",owner,target.getRootView());assertTrue(target.isClickable()&&target.isEnabled());Rect visible=new Rect();assertTrue(target.getGlobalVisibleRect(visible));assertEquals("Complete control width",target.getWidth(),visible.width());assertEquals("Complete control height",target.getHeight(),visible.height());assertTrue("48dp width",visible.width()>=Design.dp(c,48));assertTrue("48dp height",visible.height()>=Design.dp(c,48));int[] position=new int[2];target.getLocationOnScreen(position);screen.set(position[0],position[1],position[0]+target.getWidth(),position[1]+target.getHeight());});
        // Exactly one input. Never repeat a delivered action after an absent postcondition.
        assertTrue(step+": dispatched once",device.click(screen.centerX(),screen.centerY()));
    }
    private void click(String text)throws Exception{ready();input(activity.getWindow().getDecorView(),text,false);}
    private void clickDescription(String value)throws Exception{ready();input(activity.getWindow().getDecorView(),value,true);}
    private View dialog(String title)throws Exception{step="await owned "+title+" selector";View[] owner={null};await(()->{i.runOnMainSync(()->{View root=focusedWindow();if(root!=null&&root!=activity.getWindow().getDecorView()&&find(root,"Options for "+title,true)!=null)owner[0]=root;});return owner[0]!=null;});frame(owner[0]);return owner[0];}
    private void pick(String title,String value)throws Exception{clickDescription(title);choose(dialog(title),value,true);}
    private void choose(View owner,String value,boolean description)throws Exception{input(owner,value,description);step="await exact selector detachment after "+value;await(()->!owner.isAttachedToWindow());ready();frame(activity.getWindow().getDecorView());}
    private void launch()throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(SpeakChallengeActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,SpeakChallengeActivity.class).putExtra("run","private-speak").putExtra("unit",0).putExtra("request",UUID.randomUUID().toString()).putExtra("visualReview",true).putExtra("verificationLabel","TEST FIXTURE · fake microphone / no output").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(SpeakChallengeActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}require("Speak challenge",false);}
    private void recreate()throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(SpeakChallengeActivity.class.getName(),null,false);try{i.runOnMainSync(activity::recreate);activity=(SpeakChallengeActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}require("Speak challenge",false);}
    private void capture(String name)throws Exception{step="capture speak-capture-"+name;ready();frame(activity.getWindow().getDecorView());File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"speak-capture-"+name+".png")));}
    private boolean failureCaptured;
    private void failure(Throwable problem){if(failureCaptured)return;failureCaptured=true;try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());try(PrintWriter out=new PrintWriter(new File(folder,"speak-capture-failure.txt"),"UTF-8")){out.println(step);problem.printStackTrace(out);}device.takeScreenshot(new File(folder,"speak-capture-failure.png"));device.dumpWindowHierarchy(new File(folder,"speak-capture-failure.xml"));}catch(Exception diagnostic){problem.addSuppressed(diagnostic);}}
    static final class Fake implements SpeakAccess.Factory,AutoCloseable {
        final Instrumentation instrumentation=InstrumentationRegistry.getInstrumentation();final Handler main=new Handler(Looper.getMainLooper());final ExecutorService worker=Executors.newSingleThreadExecutor();SpeakAccess.Permission permission=SpeakAccess.Permission.ASK;int requests,begins,opens,closes,resumes;volatile boolean closeFailed;volatile Operation operation;final CountDownLatch inference=new CountDownLatch(1),continueInference=new CountDownLatch(1),closing=new CountDownLatch(1);CountDownLatch continueClose=new CountDownLatch(0);Runnable quiet;boolean live=true;
        public boolean current(Context c,String run,int unit){return live&&"private-speak".equals(run)&&unit==0;}public SpeakAccess.Permission permission(Activity a){return permission;}public void request(Activity a){requests++;permission=SpeakAccess.Permission.ALLOWED;}public String unavailable(Activity a){return "";}
        public SpeakAccess.Operation existing(String run,int unit,Runnable changed){if(operation==null||operation.released())return null;operation.changed=changed;return operation;}
        public SpeakAccess.Operation begin(SpeakChallengeActivity a,String run,int unit,Runnable changed){assertTrue(a.admission());assertEquals(SpeakAccess.Permission.ALLOWED,permission);assertTrue(operation==null||operation.released());begins++;operation=new Operation(a,changed);assertTrue(operation.runtime.start());return operation;}
        final class Operation implements SpeakAccess.Operation {volatile Runnable changed;final SpeakRuntime runtime;Operation(SpeakChallengeActivity activity,Runnable changed){this.changed=changed;runtime=new SpeakRuntime(new SpeakRuntime.Port(){long now;int frames;public long now(){return now;}public boolean current(){return live&&activity.foreground;}public void check(){}public SpeakRuntime.Quiet quiet(Runnable ready){quiet=ready;return ()->{if(live)resumes++;};}public SpeakRuntime.Capture open(){opens++;MicrophoneLease lease=MicrophoneLease.acquire("private-native-speak");assertNotNull(lease);return new SpeakRuntime.Capture(){public void start(){}public int read(short[] data){now+=64;return data.length;}public void close()throws Exception{closes++;closing.countDown();assertTrue(continueClose.await(30,TimeUnit.SECONDS));if(closeFailed)throw new IllegalStateException("Synthetic unconfirmed close");lease.released();}};}public SoundAnalysisStream.Model model(){return new SoundAnalysisStream.Model(){public float[] infer(float[] samples){assertEquals(15600,samples.length);frames++;if(frames==2){inference.countDown();try{assertTrue(continueInference.await(30,TimeUnit.SECONDS));}catch(InterruptedException error){throw new IllegalStateException(error);}}float[] scores=new float[521];scores[0]=.9f;return scores;}public void close(){}};}public void execute(Runnable work){worker.execute(work);}public void idle(){}public void changed(){main.post(()->{Runnable listener=Operation.this.changed;if(listener!=null)listener.run();});}});}
        public SpeakRuntime.State state(){return runtime.state;}public String error(){return runtime.error;}public int accepted(){return runtime.accepted;}public void cancel(){runtime.cancel();continueInference.countDown();}public void retry(){runtime.retryCleanup();}public boolean released(){return runtime.released();}}
        public void close()throws Exception{continueInference.countDown();continueClose.countDown();closeFailed=false;if(operation!=null){operation.cancel();if(operation.runtime.state==SpeakRuntime.State.BLOCKED)operation.retry();}worker.shutdown();assertTrue(worker.awaitTermination(8,TimeUnit.SECONDS));assertFalse(MicrophoneLease.occupied());}
    }
    private void admit()throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));assertFalse(MicrophoneLease.occupied());}
    @Test public void explicitPermissionThenQuietThenSpeechCompletesOnlyAfterFakeCaptureClose()throws Exception{admit();Map<String,?> before=new HashMap<>(Prefs.of(c).getAll());SpeakAccess.Factory previous=SpeakAccess.factory;try(Fake f=new Fake()){SpeakAccess.factory=f;try{launch();require("Allow microphone",false);capture("permission");assertEquals(0,f.begins);click("Allow microphone");await(()->f.requests==1);require("Listen for speech",false);capture("ready");assertEquals(0,f.begins);click("Listen for speech");await(()->f.operation!=null);require("Waiting for alarm sound to stop…",false);capture("quiet");assertEquals(0,f.opens);i.runOnMainSync(f.quiet);assertTrue(f.inference.await(5,TimeUnit.SECONDS));require("Listening · 1 of 2 speech windows",false);capture("listening");assertEquals(0,f.closes);f.continueInference.countDown();await(activity::isDestroyed);assertEquals(SpeakRuntime.State.DONE,f.operation.state());assertEquals(1,f.opens);assertEquals(1,f.closes);assertEquals(1,f.resumes);}catch(Exception|AssertionError error){failure(error);throw error;}finally{if(activity!=null&&!activity.isDestroyed())i.runOnMainSync(activity::finish);await(()->activity==null||activity.isDestroyed());}}finally{SpeakAccess.factory=previous;assertEquals(before,Prefs.of(c).getAll());}}
    @Test public void closingRecreationAndUnconfirmedCleanupNeverAutoRestartOrEnableFallbackEarly()throws Exception{admit();Map<String,?> before=new HashMap<>(Prefs.of(c).getAll());SpeakAccess.Factory previous=SpeakAccess.factory;try(Fake f=new Fake()){f.permission=SpeakAccess.Permission.ALLOWED;f.closeFailed=true;f.continueClose=new CountDownLatch(1);SpeakAccess.factory=f;try{launch();click("Listen for speech");await(()->f.quiet!=null);i.runOnMainSync(f.quiet);assertTrue(f.inference.await(5,TimeUnit.SECONDS));click("Stop listening");assertTrue(f.closing.await(5,TimeUnit.SECONDS));require("Stopping microphone…",false);capture("closing");recreate();require("Stopping microphone…",false);capture("recreated");assertEquals(1,f.begins);assertEquals(0,f.resumes);f.continueClose.countDown();require("Retry microphone cleanup",false);capture("cleanup");assertTrue(MicrophoneLease.occupied());f.closeFailed=false;click("Retry microphone cleanup");await(()->f.operation.released());require("Use Math instead",false);capture("error");assertEquals(1,f.resumes);assertFalse(MicrophoneLease.occupied());click("Use Math instead");await(activity::isDestroyed);assertEquals(1,f.begins);}catch(Exception|AssertionError error){failure(error);throw error;}finally{if(activity!=null&&!activity.isDestroyed())i.runOnMainSync(activity::finish);await(()->activity==null||activity.isDestroyed());}}finally{SpeakAccess.factory=previous;assertEquals(before,Prefs.of(c).getAll());}}
}
